#!/usr/bin/env bash
# Infinitary queue 12. Generated by Infinitary from one source; a newer Infinitary offers its update as a pull request, so change it there, not by hand.
# Composes a batch onto the default branch (docs/forge.md, "The shipped
# queue"): each approved change, in batch order, merged the way the host's
# merge combines its files, with a fixed author and date so every job builds
# the same commit. Nothing is pushed.
#
#   compose.sh compose <branch> <number:version>...
#     Fetches the default branch <branch> as it stands now, after the queue
#     read its changes, so a change that merged since the job checked out is
#     in the batch's base. Says "base B", the version it composes onto, then
#     merges what it can and says, one line each, "merged N", "conflict-main
#     N" (N conflicts with the default branch alone) or "conflict-batch N" (N
#     conflicts only with an earlier change here), then "tree T". It leaves
#     the checkout as is.
#   compose.sh apply <base> <tree> <number:version>...
#     Merges every change onto <base>, fails on any conflict or when the
#     result's tree is not <tree>, and checks the composed commit out.
set -euo pipefail

mode="${1:?compose or apply}"
shift
expected=""
if [ "$mode" = apply ]; then
  start="${1:?the default branch version the batch composes onto}"
  expected="${2:?the tree the queue composed}"
  shift 2
else
  branch="${1:?the default branch the batch composes onto}"
  shift
fi

export GIT_AUTHOR_NAME="Infinitary batch" GIT_AUTHOR_EMAIL="batch@infinitary.invalid"
export GIT_COMMITTER_NAME="$GIT_AUTHOR_NAME" GIT_COMMITTER_EMAIL="$GIT_AUTHOR_EMAIL"
export GIT_AUTHOR_DATE="2000-01-01T00:00:00Z" GIT_COMMITTER_DATE="2000-01-01T00:00:00Z"

# A merge needs the history back to each change's merge base: its commits
# and folders, never every past version of every file. Git downloads a
# file's contents only once the merge or the checkout reads them, so a
# shallow checkout's history stays a small, quick download.
if [ "$(git rev-parse --is-shallow-repository)" = true ]; then
  git fetch --quiet --no-tags --filter=blob:none --unshallow origin
fi

# Whether the clone holds a commit, without downloading it: after the fetch
# above, reading a missing commit would download it with its whole history
# again, where the fetch that follows a failed check takes only what the
# clone lacks. Listing it with --missing never downloads, on every git: an
# older one prints nothing for a missing commit, a newer one prints it after
# a "?".
present() {
  case "$(git rev-list --missing=print --no-walk "$1" 2>/dev/null)" in
    "" | "?"*) return 1 ;;
  esac
}

if [ "$mode" = apply ]; then
  present "$start" || git fetch --quiet --no-tags origin "$start"
  base="$(git rev-parse "$start^{commit}")"
else
  # The default branch now, never the version the job checked out: a change
  # that merged in between is not open any more, so the queue read did not
  # wait for it, and only this base carries it.
  git fetch --quiet --no-tags origin "refs/heads/$branch"
  base="$(git rev-parse "FETCH_HEAD^{commit}")"
  echo "base $base"
fi
head="$base"
for pair in "$@"; do
  number="${pair%%:*}"
  version="${pair#*:}"
  present "$version" || git fetch --quiet --no-tags origin "$version"
  if result="$(git merge-tree --write-tree --no-messages "$head" "$version")"; then
    head="$(git commit-tree "${result%%$'\n'*}" -p "$head" -p "$version" -m "Batch: #$number")"
    [ "$mode" = apply ] || echo "merged $number"
  elif [ "$mode" = apply ]; then
    echo "::error title=Batch did not compose::#$number no longer merges onto the batch"
    exit 1
  elif git merge-tree --write-tree --no-messages "$base" "$version" >/dev/null; then
    echo "conflict-batch $number"
  else
    echo "conflict-main $number"
  fi
done

tree="$(git rev-parse "$head^{tree}")"
if [ "$mode" = apply ]; then
  if [ "$tree" != "$expected" ]; then
    echo "::error title=Batch composed differently::this job built tree $tree, the batch is $expected"
    exit 1
  fi
  git checkout --quiet --detach "$head"
  echo "Composed batch $head (tree $tree) onto $base"
else
  echo "tree $tree"
fi
